  const expressions = new Map<string, string>()
  function visit(item: ts.Node) {
    if (ts.isVariableDeclaration(item) && ts.isIdentifier(item.name) &&
        ['clearPresentationError', 'published', 'off'].includes(item.name.text) && item.initializer) {
      if (expressions.has(item.name.text)) throw Error('Ambiguous actual DiagramView binding')
      expressions.set(item.name.text, item.initializer.getText(source))
