    'const clearPresentationError = ' + expressions.get('clearPresentationError') + ';\n' +
    'const published = ' + expressions.get('published') + ';\n' +
    'const diagnostic = ' + expressions.get('diagnostic') + ';\n' +
    'const off = ' + expressions.get('off') + ';\nreturn { diagnostic, off };',
    { compilerOptions: { target: ts.ScriptTarget.ES2022 } },
  ).outputText
  const setThemeError = vi.fn<(message: string | undefined) => void>(), setThemeReady = vi.fn()
  const presentation = { service, state: () => service.state(), subscribe: (notify: () => void) => service.subscribe(() => notify()) }
  const bound = new Function('presentation', 'frame', 'setThemeError', 'setThemeReady', code)(
    presentation, { current: node }, setThemeError, setThemeReady,
  ) as { diagnostic(): void; off(): void }
  return { ...bound, setThemeError, setThemeReady }
}
